"use client"

import * as React from "react"
import { createShader, shuffleAccentPalette, type ShaderController } from "glimm"
import { GlimmProvider, useGlimm, type GlimmDefaults, type Palette } from "glimm/react"

type GlimmCustomPaletteProps = Omit<GlimmDefaults, "palette"> & {
  className?: string
  initialPalette?: Palette
}

const DEFAULT_PALETTE: Palette = {
  a: [0.46, 0.88, 0.33],
  b: [0.6, 0.58, 0.74],
  c: [0.5, 0.5, 0.5],
  d: [0.54, 0.22, 0.84],
}

const BASE_PALETTE_TRANSITION_MS = 420

const clonePalette = (palette: Palette): Palette => ({
  a: [...palette.a],
  b: [...palette.b],
  c: [...palette.c],
  d: [...palette.d],
})

function interpolatePalette(from: Palette, to: Palette, result: Palette, progress: number) {
  for (const key of ["a", "b", "c"] as const) {
    for (let channel = 0; channel < 3; channel += 1) {
      result[key][channel] = from[key][channel] + (to[key][channel] - from[key][channel]) * progress
    }
  }

  for (let channel = 0; channel < 3; channel += 1) {
    let delta = to.d[channel] - from.d[channel]
    delta -= Math.round(delta)
    result.d[channel] = from.d[channel] + delta * progress
  }
}

function paletteTransitionDuration(from: Palette, to: Palette) {
  let distance = 0
  for (const key of ["a", "b", "c"] as const) {
    for (let channel = 0; channel < 3; channel += 1) {
      distance += Math.abs(to[key][channel] - from[key][channel])
    }
  }

  for (let channel = 0; channel < 3; channel += 1) {
    let delta = to.d[channel] - from.d[channel]
    delta -= Math.round(delta)
    distance += Math.abs(delta)
  }

  return Math.min(1050, BASE_PALETTE_TRANSITION_MS + 130 * distance)
}

function minimumPaletteBrightness(palette: Palette) {
  let minimum = 1
  for (let sample = 0; sample <= 40; sample += 1) {
    const t = sample / 40
    const color = palette.a.map((value, channel) =>
      Math.max(0, Math.min(1, value + palette.b[channel] * Math.cos(Math.PI * 2 * (palette.c[channel] * t + palette.d[channel])))),
    )
    minimum = Math.min(minimum, Math.max(...color))
  }
  return minimum
}

function createBrightPalette() {
  let palette = shuffleAccentPalette()
  let brightness = minimumPaletteBrightness(palette)

  for (let attempt = 0; attempt < 20 && brightness < 0.2; attempt += 1) {
    const candidate = shuffleAccentPalette()
    const candidateBrightness = minimumPaletteBrightness(candidate)
    if (candidateBrightness > brightness) {
      palette = candidate
      brightness = candidateBrightness
    }
  }

  if (brightness < 0.2) {
    const lift = 0.2 - brightness
    palette = { ...palette, a: [palette.a[0] + lift, palette.a[1] + lift, palette.a[2] + lift] }
  }

  return palette
}

function ExpandIcon() {
  return <svg aria-hidden="true" fill="none" height="18" viewBox="0 0 24 24" width="18"><path clipRule="evenodd" d="M13 3.75C13 3.33579 13.3358 3 13.75 3H20.25C20.6642 3 21 3.33579 21 3.75V10.25C21 10.6642 20.6642 11 20.25 11C19.8358 11 19.5 10.6642 19.5 10.25V5.56066L14.2803 10.7803C13.9874 11.0732 13.5126 11.0732 13.2197 10.7803C12.9268 10.4874 12.9268 10.0126 13.2197 9.71967L18.4393 4.5H13.75C13.3358 4.5 13 4.16421 13 3.75ZM3 13.75C3 13.3358 3.33579 13 3.75 13C4.16421 13 4.5 13.3358 4.5 13.75V18.4393L9.71967 13.2197C10.0126 12.9268 10.4874 12.9268 10.7803 13.2197C11.0732 13.5126 11.0732 13.9874 10.7803 14.2803L5.56066 19.5H10.25C10.6642 19.5 11 19.8358 11 20.25C11 20.6642 10.6642 21 10.25 21H3.75C3.33579 21 3 20.6642 3 20.25V13.75Z" fill="currentColor" fillRule="evenodd" /></svg>
}

function ShuffleIcon() {
  return <svg aria-hidden="true" fill="none" height="14" viewBox="0 0 24 24" width="14"><path clipRule="evenodd" d="M17.7197 3.21967C18.0126 2.92678 18.4874 2.92678 18.7803 3.21967L21.7803 6.21967C22.0732 6.51256 22.0732 6.98744 21.7803 7.28033L18.7803 10.2803C18.4874 10.5732 18.0126 10.5732 17.7197 10.2803C17.4268 9.98744 17.4268 9.51256 17.7197 9.21967L19.4393 7.5H17.0781C16.7467 7.5 16.4289 7.63159 16.1945 7.86585L5.92144 18.1326C5.40576 18.648 4.70654 18.9375 3.97748 18.9375H2.75C2.33579 18.9375 2 18.6017 2 18.1875C2 17.7733 2.33579 17.4375 2.75 17.4375H3.97748C4.30887 17.4375 4.6267 17.3059 4.8611 17.0717L15.1341 6.80487C15.6498 6.2895 16.349 6 17.0781 6H19.4393L17.7197 4.28033C17.4268 3.98744 17.4268 3.51256 17.7197 3.21967ZM2 5.75C2 5.33579 2.33579 5 2.75 5H3.92157C4.65092 5 5.35039 5.28973 5.86612 5.80546L9.03033 8.96967C9.32322 9.26256 9.32322 9.73744 9.03033 10.0303C8.73744 10.3232 8.26256 10.3232 7.96967 10.0303L4.80546 6.86612C4.57104 6.6317 4.25309 6.5 3.92157 6.5H2.75C2.33579 6.5 2 6.16421 2 5.75ZM17.6372 13.5313C17.9306 13.2389 18.4055 13.2397 18.6979 13.5331L21.7812 16.6268C22.0729 16.9195 22.0729 17.393 21.7812 17.6857L18.6979 20.7794C18.4055 21.0728 17.9306 21.0736 17.6372 20.7812C17.3438 20.4888 17.343 20.014 17.6354 19.7206L19.4436 17.9062H16.9496C16.2121 17.9062 15.5055 17.61 14.9885 17.0841L12.9651 15.0258C12.6748 14.7304 12.6788 14.2555 12.9742 13.9651C13.2696 13.6748 13.7445 13.6788 14.0349 13.9742L16.0582 16.0325C16.2932 16.2716 16.6144 16.4062 16.9496 16.4062H19.4436L17.6354 14.5919C17.343 14.2985 17.3438 13.8237 17.6372 13.5313Z" fill="currentColor" fillRule="evenodd" /></svg>
}

function PaletteCanvas({ palette }: { palette: Palette }) {
  const canvasRef = React.useRef<HTMLCanvasElement>(null)
  const controllerRef = React.useRef<ShaderController | null>(null)
  const currentPaletteRef = React.useRef(clonePalette(palette))
  const fromPaletteRef = React.useRef(clonePalette(palette))
  const toPaletteRef = React.useRef(clonePalette(palette))
  const transitionStartedAtRef = React.useRef(0)
  const transitionDurationRef = React.useRef(BASE_PALETTE_TRANSITION_MS)

  React.useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas) return
    const controller = createShader({ canvas, palette, bandTight: 14, direction: "ltr" })
    if (!controller) return

    controllerRef.current = controller
    controller.setAlpha(1)
    controller.setProgress(0.5)
    controller.setWaveAmount(0)

    return () => {
      controller.destroy()
      controllerRef.current = null
    }
  }, [])

  React.useEffect(() => {
    fromPaletteRef.current = clonePalette(currentPaletteRef.current)
    toPaletteRef.current = clonePalette(palette)
    transitionDurationRef.current = paletteTransitionDuration(fromPaletteRef.current, toPaletteRef.current)
    transitionStartedAtRef.current = performance.now()
  }, [palette])

  React.useEffect(() => {
    let frame = 0
    const animate = () => {
      const elapsed = performance.now() - transitionStartedAtRef.current
      const rawProgress = Math.max(0, Math.min(1, elapsed / transitionDurationRef.current))
      const easedProgress = 1 - Math.pow(1 - rawProgress, 3)
      interpolatePalette(fromPaletteRef.current, toPaletteRef.current, currentPaletteRef.current, easedProgress)
      controllerRef.current?.setPalette(currentPaletteRef.current)
      frame = requestAnimationFrame(animate)
    }

    frame = requestAnimationFrame(animate)
    return () => cancelAnimationFrame(frame)
  }, [])

  return <canvas ref={canvasRef} aria-hidden="true" style={{ display: "block", inset: 0, height: "100%", position: "absolute", width: "100%" }} />
}

function CustomPalettePanel({ initialPalette }: { initialPalette: Palette }) {
  const [palette, setPalette] = React.useState<Palette>(initialPalette)
  const { sweep } = useGlimm()
  const preview = React.useCallback(() => sweep(async () => {}, { palette }), [palette, sweep])
  const shuffle = () => setPalette(createBrightPalette())

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: "13px" }}>
      <div style={{ aspectRatio: "16 / 9", background: "#fff", borderRadius: "8px", boxShadow: "inset 0 0 0 0.5px rgba(0,0,0,0.06)", overflow: "hidden", position: "relative", width: "100%" }}>
        <PaletteCanvas palette={palette} />
        <div aria-hidden="true" style={{ background: "radial-gradient(ellipse 70% 78% at 50% 50%, rgba(255,255,255,0) 55%, rgba(255,255,255,0.7) 82%, #fff 100%)", inset: 0, pointerEvents: "none", position: "absolute" }} />
        <button aria-label="Preview on page" onClick={preview} type="button" style={{ alignItems: "center", background: "transparent", border: "none", color: "#bfbfbf", cursor: "pointer", display: "inline-flex", height: "30px", justifyContent: "center", padding: 0, position: "absolute", right: "10px", top: "10px", width: "30px", zIndex: 3 }}><ExpandIcon /></button>
      </div>
      <div style={{ display: "flex", justifyContent: "flex-end" }}>
        <button aria-label="Shuffle a new palette" onClick={shuffle} type="button" style={{ alignItems: "center", background: "#242529", border: "none", borderRadius: "999px", boxShadow: "0 0 0 0.75px #27272a inset, 0 0 0 1.25px rgba(255,255,255,0.30) inset, 0 8px 16px rgba(0,0,0,0.08), 0 16px 32px rgba(0,0,0,0.08)", color: "#fff", cursor: "pointer", display: "inline-flex", fontFamily: "Inter, ui-sans-serif, system-ui, sans-serif", fontSize: "12px", fontWeight: 450, gap: "6px", height: "28px", padding: "0 12px 0 10px" }}><ShuffleIcon />Shuffle</button>
      </div>
    </div>
  )
}

function GlimmCustomPalette({ className, initialPalette = DEFAULT_PALETTE, ...defaults }: GlimmCustomPaletteProps) {
  return <GlimmProvider zIndex={100000} bandTight={40} peakAlpha={0.75} reducedMotion="sweep" {...defaults}><main className={className} style={{ alignItems: "center", background: "#fff", color: "#242529", display: "flex", justifyContent: "center", minHeight: "100vh", padding: "48px 32px", width: "100%" }}><section style={{ maxWidth: "634px", width: "100%" }}><CustomPalettePanel initialPalette={initialPalette} /></section></main></GlimmProvider>
}

export { DEFAULT_PALETTE, GlimmCustomPalette }
export default GlimmCustomPalette

